codeSample:
POST /books/_update/kLEHMYkBq7V9x4qGJOnh
{
  "doc": {
    "price": 14.99
  }
}
// 只传变更字段，避免整文档往返

PUT /books/_doc/kLEHMYkBq7V9x4qGJOnh?version=1
{ "price": 13.99 }
# 若当前 _version 不等于 1，请求失败，客户端重试

GET /books/_search
{
  "query": { "bool": { "must": [
    { "match": { "title": "Great" } },
    { "range": { "price": { "lte": 15 } } }
  ]}}
}
// must 里的多个子查询是 AND 关系

GET /books/_search
{
  "query": { "nested": {
    "path": "reviews",
    "query": { "bool": { "must": [
      { "match": { "reviews.comment": "excellent" } },
      { "range": { "reviews.rating": { "gte": 4 } } }
    ]}}
  }}
}
// path 进入 nested 的独立字段空间

GET /restaurants/_search
{
  "query": { "geo_distance": {
    "distance": "5km",
    "location": { "lat": 40.7128, "lon": -74.0060 }
  }}
}
// distance 定义半径，location 是圆心

PUT /restaurants
{ "mappings": { "properties": {
  "location": { "type": "geo_point" }
}}}
// geo_point 底层由 BKD tree 索引坐标

GET /books/_search
{
  "sort": [{ "_script": {
    "type": "number",
    "script": { "source": "doc['price'].value * 0.9" },
    "order": "asc"
  }}]
}
// 用 Painless 脚本按派生值排序

GET /books/_search
{
  "sort": [{ "reviews.rating": {
    "order": "desc",
    "mode": "max",
    "nested": { "path": "reviews" }
  }}]
}
// mode: max 从每本书的多条评论里取最高分
